const fs = require("fs");
function sub(file, from, to) {
  const s = fs.readFileSync(file, "utf8");
  if (!s.includes(from)) throw new Error(file + ": missing " + from.slice(0, 60));
  fs.writeFileSync(file, s.replace(from, to));
}
// formatting.ts
sub("src/formatting.ts", /\/\*\* How to read the thread with git, for the job summary\. \*\/[\s\S]*?\n}\n\n/.source ? fs.readFileSync("src/formatting.ts","utf8").match(/\/\*\* How to read the thread with git, for the job summary\. \*\/[\s\S]*?\n}\n\n/)[0] : "", "");
// run.ts
sub("src/run.ts", "\tformatThreadSummary,\n", "");
const rs = fs.readFileSync("src/run.ts","utf8");
const old = rs.match(/\/\*\*\n \* After the final push[\s\S]*?\n}\n/)[0];
sub("src/run.ts", old, "/** After the final push: where the thread is now, in the log. Each comment says how to read it (#80). */\nfunction showThread(deps: ActionDependencies, thread: Thread, ref: string): void {\n\tconst { tip } = thread;\n\tdeps.log.info(\n\t\t\`🧵 \${ref} is at \${tip === undefined ? \"(nothing stored)\" : tip.slice(0, 7)}\`,\n\t);\n}\n");
sub("src/run.ts", "await showThread(deps, thread, thread.ref);", "showThread(deps, thread, thread.ref);");
// formatting.test.ts
sub("src/formatting.test.ts", "\tformatThreadSummary,\n", "");
sub("src/formatting.test.ts", 'describe("formatThreadLog / formatThreadSummary"', 'describe("formatThreadLog"');
const ft = fs.readFileSync("src/formatting.test.ts","utf8");
const sumExp = ft.match(/\t\texpect\(formatThreadSummary\("refs\/pi\/threads\/42", "upstream"\)\)[\s\S]*?\n\t\t\);\n/)[0];
sub("src/formatting.test.ts", sumExp, "");
sub("src/formatting.test.ts", 'const sample = formatThreadSummary("refs/pi/threads/42", "origin");', 'const sample = formatSuccessComment("ok", "refs/pi/threads/42");');
