sub("src/run.test.ts", "\t\t// In comment mode, the reply says how to read the thread, collapsed; the job summary does not (#80).\n", "\t\t// The reply says how to read the thread, collapsed; the job summary does not repeat it (#80).\n");
const rt = fs.readFileSync("src/run.test.ts","utf8");
const om = rt.match(/\t\tconst summary = vi\.fn\(async \(_markdown: string\) => \{\n\t\t\tthrow new Error\("no summary file"\);\n\t\t\}\);\n\t\tconst deps = \{\n\t\t\t\.\.\.w\.deps\(w\.comment\("@pi check"\), \{ outputMode: "output" \}\),\n\t\t\tsummary,\n\t\t\};\n/)[0];
sub("src/run.test.ts", om, '\t\tconst deps = w.deps(w.comment("@pi check"), { outputMode: "output" });\n');
const tail = rt.match(/\t\t\/\/ A job summary that cannot be written is a warning; the log still shows the thread\.\n[\s\S]*?"Could not write the job summary: no summary file",\n\t\t\);\n/)[0];
sub("src/run.test.ts", tail, '\t\t// The log shows how to read the thread; the job summary does not (#80).\n\t\texpect(deps.log.startGroup).toHaveBeenCalledWith(\`🧵 Thread \${REF}: new\`);\n\t\texpect(deps.summary).not.toHaveBeenCalled();\n');
